/**
 * EVENT-role leaves as DSL triggers, split out of `compile-conditions.ts`: the fixed kinds'
 * table, phase/turn/step boundaries, the general owned moments, and a folded unit-filter as the
 * acting unit. Used from `compile.ts` and the containers.
 */

import { attackTypeCondition } from "./compile-conditions.js";
import { closed, CompileError, type CompileLeaf } from "./compile-fragments.js";
import { weaponScope } from "./compile-weapon-effects.js";
import { OWNED_EVENT_KINDS } from "./families/vocabulary.js";
import { TRIGGER_ROLL_KINDS } from "./families/vocabulary.js";
import { ANTECEDENT } from "./antecedent-families.js";
import { STEP_PHASES } from "./compile-step-window.js";

type Node = Record<string, unknown>;

const TRIGGERS: Record<string, Node> = {
  "event:charge": { event: "move-ended", filter: { move_types: ["charge"] } },
  "event:unit-destroyed": { event: "destroyed" },
  "event:model-destroyed": { event: "model-destroyed", object: "model-in-this-unit" },
  "event:this-model-destroyed": { event: "model-destroyed", object: "this-model", filter: { timing: "before-removal" } },
  // Having shot is the unit's own shooting attacks resolved, in whichever phase it shot.
  "event:after-shooting": { event: "attacks-resolved", filter: { kind: "shoot" } },
  "event:selected-to-shoot": { event: "selected", filter: { to: "shoot" } },
  "event:selected-to-fight": { event: "selected", filter: { to: "fight" } },
  // Enemy moments name the enemy unit as the one acting, and this unit as what it acts on.
  "event:enemy-selected-targets": { event: "targets-selected", filter: { kind: "attack" }, subject: { owner: "enemy" }, object: "this-unit" },
  "event:enemy-ended-move": { event: "move-ended", subject: { owner: "enemy" } },
  "event:enemy-has-shot": { event: "attacks-resolved", filter: { kind: "shoot" }, subject: { owner: "enemy" } },
  "event:enemy-declared-charge": { event: "targets-selected", filter: { kind: "charge" }, subject: { owner: "enemy" } },
  "event:army-selected": { event: "army-selected" },
  "turn-start:player-turn": { event: "turn-started", condition: { type: "player-turn-is", parameters: { turn: "your-turn" } } },
  "turn-start:opponent-turn": { event: "turn-started", condition: { type: "player-turn-is", parameters: { turn: "opponent-turn" } } },
  "turn-start:any-turn": { event: "turn-started" },
  "turn-start:battle-round": { event: "round-started" },
  // Bare game-clock and history moments with no narrowing of their own.
  "event:battle-started": { event: "battle-started" },
  "event:deployment-ended": { event: "deployment-ended" },
  "event:round-ended": { event: "round-ended" },
  "event:disembarked": { event: "disembarked" },
  "event:damage-allocated": { event: "damage-allocated" },
  // More bare moments.
  "event:battle-formations-declared": { event: "battle-formations-declared" },
  "event:objective-gained": { event: "objective-gained" },
};

/** A phase-boundary trigger, narrowed by phase and whose turn unless either is "any". */
function phaseTrigger(leaf: CompileLeaf): Node | null {
  const event = leaf.parameters.kind === "phase-start" ? "phase-started" : leaf.parameters.kind === "phase-end" ? "phase-ended" : null;
  if (!event) return null;
  const operands = phaseTurnOperands(leaf);
  if (operands.length === 0) return { event };
  return { event, condition: operands.length === 1 ? operands[0] : { operator: "and", operands } };
}

/** The phase-is and player-turn-is operands a leaf names, unless it says any phase or either turn. */
function phaseTurnOperands(leaf: CompileLeaf): Node[] {
  const operands: Node[] = [];
  if (leaf.parameters.phase && leaf.parameters.phase !== "any") operands.push({ type: "phase-is", parameters: { phase: leaf.parameters.phase } });
  // The DSL spells whose turn as the schema's player-turn enum does.
  if (leaf.parameters.turn && leaf.parameters.turn !== "either") operands.push({ type: "player-turn-is", parameters: { turn: `${String(leaf.parameters.turn)}-turn` } });
  return operands;
}

/** A turn-boundary trigger (turn-ended), narrowed by whose turn unless "either". */
function turnEndedTrigger(leaf: CompileLeaf): Node {
  const turn = leaf.parameters.turn;
  if (!turn || turn === "either") return { event: "turn-ended" };
  return { event: "turn-ended", condition: { type: "player-turn-is", parameters: { turn: `${String(turn)}-turn` } } };
}

/** A trigger narrowed to one player's turn, unless the leaf says either or nothing. */
function withTurn(node: Node, leaf: CompileLeaf): Node {
  const turn = leaf.parameters.turn;
  if (turn === undefined || turn === "either") return node;
  return { ...node, condition: { type: "player-turn-is", parameters: { turn: `${String(closed(leaf, "turn"))}-turn` } } };
}

/** A before-roll or after-roll filter's roll: a kind the DSL trigger can name, never any, all or attacks. */
function triggerRoll(leaf: CompileLeaf): unknown {
  const roll = closed(leaf, "roll");
  if (!(TRIGGER_ROLL_KINDS as readonly unknown[]).includes(roll)) throw new CompileError(`A ${String(leaf.parameters.kind)} moment names roll ${JSON.stringify(roll)}, which a DSL trigger cannot name; name the roll kinds it covers.`);
  return roll;
}

/**
 * The triggers one EVENT leaf lowers to: a list of roll kinds (`rolls`) is one trigger
 * per kind, in the listed order, each with that kind as its roll. Every other leaf is one trigger.
 */
export function triggerLeaves(leaf: CompileLeaf): CompileLeaf[] {
  if (leaf.family_id === "event" && leaf.parameters.kind === "unit-or-model-destroyed") {
    return ["unit-destroyed", "model-destroyed"].map((kind) => ({ ...leaf, parameters: { ...leaf.parameters, kind } }));
  }
  // "The Fire Overwatch/Heroic Intervention Stratagem": one trigger per rule, any one of which fires it.
  if (leaf.family_id === "event" && Array.isArray(leaf.parameters.ids)) {
    const { ids, ...rest } = leaf.parameters as { ids: unknown[] } & Record<string, unknown>;
    return ids.map((id) => ({ ...leaf, parameters: { ...rest, id } }));
  }
  if (leaf.family_id !== "event" || !Array.isArray(leaf.parameters.rolls)) return [leaf];
  const { rolls, ...rest } = leaf.parameters as { rolls: unknown[] } & Record<string, unknown>;
  return rolls.map((roll) => ({ ...leaf, parameters: { ...rest, roll } }));
}

/**
 * "When this model uses its Foo ability", "each time a friendly unit performs the Bar Agile
 * Manoeuvre": which rule was used (filter.id) and who used it. This unit is the DSL's default.
 */
function usedTrigger(leaf: CompileLeaf): Node {
  const subject = leaf.parameters.subject;
  if (subject !== undefined && leaf.parameters.subject_filter !== undefined) throw new CompileError("A used moment names who used the rule twice: by its subject and by the unit-filter before it.");
  // An aura's recipient is no unit outside the aura: compile-named-ability.ts folds that moment into the trigger's proximity.
  if (subject === "recipient") throw new CompileError("A used moment of an aura's recipient must follow its aura-range directly, in the same sentence, to become the trigger's subject and proximity.");
  // "When a unit chosen by a Gadget is used": the chosen unit is not who used the rule (compile-named-ability.ts).
  if (leaf.parameters.object === "antecedent") throw new CompileError("A used moment's unit is the one that used the rule; an earlier leaf's unit as the object of a use is not who used it.");
  const source = leaf.parameters.source;
  const usage = leaf.parameters.usage;
  const bindAs = leaf.parameters.bind_as;
  const sources = source === undefined ? undefined : Array.isArray(source) ? source : null;
  const usageValue = usage === undefined ? undefined : usage !== null && typeof usage === "object" && !Array.isArray(usage) ? usage as Record<string, unknown> : null;
  if (sources === null || (source !== undefined && leaf.parameters.activity !== "ability")) throw new CompileError("A used-ability source qualifier needs an ability activity and a source list.");
  if (usageValue === null || (usage !== undefined && leaf.parameters.activity !== "ability")) throw new CompileError("A used-ability usage qualifier needs an ability activity and a usage object.");
  if ((source !== undefined || usage !== undefined) && bindAs === undefined) throw new CompileError("A qualified used ability must bind its exact used event.");
  if (bindAs !== undefined && typeof bindAs !== "string") throw new CompileError("A used ability event binding must be a string.");
  if (usageValue !== undefined && (usageValue.frequency !== "n-per-battle" || usageValue.count !== 1)) throw new CompileError("A used-ability usage qualifier must be once per battle.");
  if (sources !== undefined && (sources.length < 1 || sources.some((value) => value !== "unit" && value !== "enhancement"))) throw new CompileError("A used-ability source qualifier must list unit and/or enhancement.");
  if (sources !== undefined && new Set(sources).size !== sources.length) throw new CompileError("A used-ability source qualifier lists a source twice.");
  // "Makes a Dark Pact and does not fail the resulting Leadership test": the test's outcome is the moment,
  // and binds that test for a later "if the result of that test was 8 or more" (compile-dark-pact.ts).
  if (leaf.parameters.passed !== undefined) {
    return {
      event: "after-roll",
      filter: { roll: "dark-pact", result: leaf.parameters.passed === true ? "success" : "failure" },
      ...(subject !== undefined && subject !== "this-unit" ? { subject: closed(leaf, "subject") } : {}),
      ...(leaf.parameters.owner !== undefined ? { subject: { owner: closed(leaf, "owner") } } : {}),
    };
  }
  const filter = {
    kind: closed(leaf, "activity"),
    ...(leaf.parameters.id !== undefined ? { id: closed(leaf, "id") } : {}),
    ...(leaf.parameters.ability_keyword !== undefined ? { ability_keyword: closed(leaf, "ability_keyword") } : {}),
    ...(sources !== undefined ? { source: [...sources] } : {}),
    ...(usageValue !== undefined ? { usage: { ...usageValue } } : {}),
  };
  const binding = bindAs !== undefined ? { binds_event_variable: bindAs } : {};
  return {
    event: "used",
    filter,
    ...(leaf.parameters.owner !== undefined ? { subject: { owner: closed(leaf, "owner") } } : {}),
    ...(subject !== undefined && subject !== "this-unit" ? { subject: closed(leaf, "subject") } : {}),
    ...(leaf.parameters.targets_level !== undefined ? { object: { owner: "any", level: closed(leaf, "targets_level") } } : {}),
    // "When this unit is issued an Order": the unit the used rule is aimed at.
    ...(leaf.parameters.object !== undefined ? { object: closed(leaf, "object") } : {}),
    ...binding,
  };
}

/**
 * "When you spend 1 Foo token to Empower …", "… to perform a Baz Manoeuvre": the pool spent and, when
 * the leaf names it, what the spend was for (filter.kind or filter.tag) and the unit it serves.
 * A spend for an earlier leaf's unit takes that unit from its folded filter (compile-named-ability.ts).
 */
function spentTrigger(leaf: CompileLeaf): Node {
  const object = leaf.parameters.object;
  if (object === ANTECEDENT) throw new CompileError("A spend for an earlier leaf's unit needs that unit's filter and range right before the spend or right after it, in its sentence.");
  return {
    event: "resource-spent",
    filter: {
      pool: closed(leaf, "pool"),
      ...(leaf.parameters.activity !== undefined ? { kind: closed(leaf, "activity") } : {}),
      ...(leaf.parameters.tag !== undefined ? { tag: closed(leaf, "tag") } : {}),
    },
    ...(object !== undefined ? { object: closed(leaf, "object") } : {}),
    // "Empower units from your army … by spending Pain tokens": whose unit the spend serves.
    ...(leaf.parameters.object_owner !== undefined ? { object: { owner: closed(leaf, "object_owner") } } : {}),
  };
}

/** Event kinds that need one extra filter field the bare `TRIGGERS` table cannot carry. */
const V7_FILTERED_KINDS: Record<string, (leaf: CompileLeaf) => Node> = {
  "turn-ended": turnEndedTrigger,
  "step-started": (leaf) => withTurn({ event: "step-started", filter: { step: closed(leaf, "step") } }, leaf),
  used: usedTrigger,
  // A strength threshold in place of a state ("become Below Half-strength").
  "state-changed": (leaf) => ({
    event: "state-changed",
    filter: {
      ...(leaf.parameters.strength !== undefined ? { strength: closed(leaf, "strength") } : { state: closed(leaf, "state") }),
      // "Caused an enemy unit … to become Below Half-strength": the unit whose attacks did it.
      ...(leaf.parameters.by !== undefined ? { by: closed(leaf, "by") } : {}),
    },
    ...(leaf.parameters.owner !== undefined ? { subject: { owner: closed(leaf, "owner") } } : {}),
  }),
  "designation-changed": (leaf) => ({ event: "designation-changed", filter: { tag: closed(leaf, "tag") } }),
  "designation-resolved": (leaf) => ({ event: "designation-resolved", filter: { tag: closed(leaf, "tag") } }),
  "before-roll": (leaf) => ({ event: "before-roll", filter: { roll: triggerRoll(leaf) } }),
  "after-roll": (leaf) => ({
    event: "after-roll", filter: { roll: triggerRoll(leaf), ...(leaf.parameters.result !== undefined ? { result: closed(leaf, "result") } : {}),
      // "on an unmodified 6" after the moment (compile-roll-faces.ts).
      ...(leaf.parameters.unmodified !== undefined ? { unmodified: leaf.parameters.unmodified } : {}) },
    // The WHEN moment's unit, which a Stratagem's nested roll moment names (compile-when-subject.ts).
    ...(typeof leaf.parameters.subject_var === "string" ? { subject: { event_var: leaf.parameters.subject_var } }
      : leaf.parameters.subject !== undefined && leaf.parameters.subject !== "this-unit" ? { subject: closed(leaf, "subject") } : {}),
  }),
  "marker-removed": (leaf) => ({ event: "marker-removed", filter: { marker: closed(leaf, "marker") } }),
  "resource-gained": (leaf) => ({
    event: "resource-gained",
    // "Each time your opponent gains a CP as the result of an ability": whose gain, and what caused it.
    filter: { pool: closed(leaf, "pool"), ...(leaf.parameters.source !== undefined ? { via: closed(leaf, "source") } : {}) },
    ...(leaf.parameters.owner !== undefined ? { subject: { owner: closed(leaf, "owner") } } : {}),
  }),
  "resource-spent": spentTrigger,
};

export function kindKey(leaf: CompileLeaf): string {
  return `${leaf.family_id}:${String(leaf.family_id === "turn-start" ? leaf.parameters.turn : leaf.parameters.kind)}`;
}

/** The general moments (OWNED_EVENT_KINDS and move-started): any owner, and their own move_types/to/action_kind filter. */
function ownedEventTrigger(leaf: CompileLeaf): Node {
  const node: Node = { event: closed(leaf, "kind") };
  if (leaf.parameters.owner !== undefined) node.subject = { owner: closed(leaf, "owner") };
  // An explicit subject other than this unit (the default) names whose moment it is.
  if (leaf.parameters.subject !== undefined && leaf.parameters.subject !== "this-unit") node.subject = closed(leaf, "subject");
  const filter: Node = {};
  if (leaf.parameters.move_types !== undefined) filter.move_types = closed(leaf, "move_types");
  // The disembark mode a unit is selected to move with.
  if (leaf.parameters.mode !== undefined) filter.mode = closed(leaf, "mode");
  // "But if it does, after it has moved": the move passed through the named terrain (compile-passthrough-used.ts).
  if (leaf.parameters.through !== undefined) filter.through = closed(leaf, "through");
  // Selected "to charge" is selected to declare a charge, which the DSL spells declare-charge.
  if (leaf.parameters.to !== undefined) filter.to = closed(leaf, "to") === "charge" ? "declare-charge" : closed(leaf, "to");
  if (leaf.parameters.action_kind !== undefined) filter.kind = closed(leaf, "action_kind");
  // Where a set-up moment brings the unit from ("set up … from Reserves").
  if (leaf.parameters.from !== undefined) filter.from = closed(leaf, "from");
  // "Each time you target this unit with the Foo Stratagem": which Stratagem.
  if (leaf.parameters.id !== undefined) {
    if (filter.kind !== "stratagem") throw new CompileError("A targeting names its ability through a by-ability leaf, with the unit whose ability it is.");
    filter.id = closed(leaf, "id");
  }
  // "Select a target for this model's twin tesla destructor": which weapon's targeting (compile-weapon-qualified.ts).
  if (leaf.parameters.targeting_weapons !== undefined) {
    filter.weapons = weaponScope({ ...leaf, parameters: leaf.parameters.targeting_weapons as Node }).weapons;
  }
  if (Object.keys(filter).length) node.filter = filter;
  // "In your opponent's Shooting phase" on an attacks-resolved moment: the trigger's own condition.
  const timing = phaseTurnOperands(leaf);
  if (timing.length) {
    if (leaf.parameters.kind !== "attacks-resolved") throw new CompileError("Only an attacks-resolved moment names its phase and turn among the owned moments.");
    node.condition = timing.length === 1 ? timing[0] : { operator: "and", operands: timing };
  }
  // "Selected by a friendly X unit's Foo ability" (compile-named-ability.ts): the selecting ability
  // and its user; the trigger's subject is the selected unit, any unit unless the moment names one.
  if (filter.kind === "ability") {
    if (leaf.parameters.source_ability === undefined) throw new CompileError("A unit selected by an ability needs a by-ability leaf naming that ability and the unit whose ability it is.");
    node.source_ability = structuredClone(leaf.parameters.source_ability);
    node.subject ??= { owner: "any" };
  }
  // "Each time you target the bearer with a Stratagem": what the moment was done to.
  if (leaf.parameters.object === "antecedent") throw new CompileError("A moment that names an earlier leaf's unit as its object needs that unit's aura, which names the unit and its range.");
  if (leaf.parameters.object !== undefined) node.object = closed(leaf, "object");
  return node;
}

function destructionRelationCondition(relation: unknown, eventVariable: unknown, direction: "caused_by" | "causes"): Node {
  if (relation === null || typeof relation !== "object" || Array.isArray(relation) || typeof eventVariable !== "string") {
    throw new CompileError("An exact destruction relation needs an object and a bound event variable.");
  }
  const alternatives = Object.entries(relation as Record<string, unknown>).map(([kind, value]) => {
    if (value === null || typeof value !== "object" || Array.isArray(value)) throw new CompileError("A destruction relation needs an object filter.");
    const { within, ...objectFilter } = value as Record<string, unknown>;
    const proximity = within as { inches: number; of: string } | undefined;
    return {
      type: "happened",
      parameters: {
        event: kind === "model" ? "model-destroyed" : "destroyed",
        object: { ...objectFilter, ...(kind === "model" ? { level: "model" } : {}) },
        filter: { [direction]: { event_var: eventVariable } },
        window: "event",
        ...(proximity !== undefined ? { proximity: { of: proximity.of, range: { inches: proximity.inches } } } : {}),
      },
    };
  });
  return alternatives.length === 1 ? alternatives[0]! : { operator: "or", operands: alternatives };
}

export function trigger(leaf: CompileLeaf): Node {
  // A list of roll kinds is several triggers; a caller that takes one trigger must use triggerLeaves().
  if (Array.isArray(leaf.parameters.rolls)) throw new CompileError("A moment that names several rolls lowers to one trigger per roll; it cannot be one trigger.");
  if (Array.isArray(leaf.parameters.ids)) throw new CompileError("A moment that names several rules lowers to one trigger per rule; it cannot be one trigger.");
  if (leaf.parameters.object === "filtered-units") throw new CompileError("A used moment aimed at a unit-filter's units needs that unit-filter right before it, in its sentence.");
  const node = eventTrigger(leaf);
  // "… makes a melee attack that destroys an enemy model, after all its attacks have been resolved"
  // (compile-weapon-qualified.ts): those attacks destroyed it, so the destruction is a happened
  // condition on the attacks-resolved moment, looking back over that event.
  if (leaf.parameters.destroyed_during !== undefined) {
    // "… that destroy a unit or cause it to become Below Half-strength": either happening during those attacks.
    const during = leaf.parameters.destroyed_during as CompileLeaf;
    const happenings = [during, ...((during.parameters.or_during as CompileLeaf[] | undefined) ?? [])].map((moment): Node => {
      const { event, subject, object, filter } = trigger(moment);
      return { type: "happened", parameters: {
        event, ...(subject !== undefined ? { subject } : {}), ...(object !== undefined ? { object } : {}), ...(filter !== undefined ? { filter } : {}), window: "event",
      } };
    });
    const happened: Node = happenings.length === 1 ? happenings[0]! : { operator: "or", operands: happenings };
    node.condition = node.condition === undefined ? happened : { operator: "and", operands: [node.condition, happened] };
  }
  // Attack classifications which describe the event itself stay on its event filter. A mortal
  // damage allocation and Psychic attacks are not inferred from a concurrent attack predicate.
  if (leaf.family_id === "event" && leaf.parameters.attack_type !== undefined && leaf.parameters.attack_type !== "any") {
    const attackType = closed(leaf, "attack_type");
    if (attackType === "mortal" || leaf.parameters.kind === "attacks-resolved" || leaf.parameters.kind === "model-destroyed") {
      const filter = (node.filter ?? {}) as Node;
      node.filter = { ...filter, attack_type: attackType };
    } else {
      const type = attackTypeCondition({ ...leaf, parameters: { attack_type: attackType } });
      if (type) node.condition = node.condition === undefined ? type : { operator: "and", operands: [node.condition, type] };
    }
  }
  // Reviewed event-family leaves name exact event identity with bind_as; folded compiler leaves
  // use binds_event_variable. Both lower to the one canonical trigger property.
  const eventBinding = leaf.parameters.bind_as ?? leaf.parameters.binds_event_variable;
  if (eventBinding !== undefined && leaf.family_id === "event") node.binds_event_variable = closed({ ...leaf, parameters: { event_binding: eventBinding } }, "event_binding");
  // A folded unit-filter (compile-unit-filters.ts) names the unit whose action fires it.
  if (leaf.parameters.subject_filter !== undefined) node.subject = structuredClone(leaf.parameters.subject_filter as Node);
  // An aura's recipient's moment (compile-named-ability.ts): within the aura's range of its holder.
  if (leaf.parameters.proximity !== undefined) {
    const { of, inches } = leaf.parameters.proximity as { of: string; inches: number };
    node.proximity = { of, range: { inches } };
  }
  // "The Reinforcements step of your opponent's Movement phase, just after …" (compile-step-window.ts): the step it happens in.
  if (leaf.parameters.step_window !== undefined) {
    const { step, turn } = leaf.parameters.step_window as { step: string; turn?: string };
    const window: Node[] = [{ type: "phase-is", parameters: { phase: STEP_PHASES[step], step } }];
    if (turn !== undefined) window.push({ type: "player-turn-is", parameters: { turn: `${turn}-turn` } });
    const existing = node.condition === undefined ? [] : (node.condition as Node).operator === "and" ? [...((node.condition as Node).operands as Node[])] : [node.condition as Node];
    const operands = [...window, ...existing];
    node.condition = operands.length === 1 ? operands[0] : { operator: "and", operands };
  }
  // "Using its Foo ability" (compile-named-ability.ts): the moment's unit used that ability in it.
  if (leaf.parameters.by_ability !== undefined) {
    const subject = typeof node.subject === "string" ? node.subject : node.subject === undefined ? undefined : "event-subject";
    const used: Node = { type: "happened", parameters: { event: "used", ...(subject !== undefined && subject !== "this-unit" ? { subject } : {}), filter: { kind: "ability", id: leaf.parameters.by_ability }, window: "event" } };
    node.condition = node.condition === undefined ? used : { operator: "and", operands: [node.condition, used] };
  }
  // "an Agile Manoeuvre that involves rolling a D6" (compile-manoeuvre-own-roll.ts): one of the named manoeuvres was used.
  if (leaf.parameters.manoeuvre_ids !== undefined) {
    const subject = typeof node.subject === "string" ? node.subject : node.subject === undefined ? undefined : "event-subject";
    const ids = closed(leaf, "manoeuvre_ids") as string[];
    const used = ids.map((id): Node => ({ type: "happened", parameters: { event: "used", ...(subject !== undefined && subject !== "this-unit" ? { subject } : {}), filter: { kind: "manoeuvre", id }, window: "event" } }));
    const either: Node = used.length === 1 ? used[0]! : { operator: "or", operands: used };
    node.condition = node.condition === undefined ? either : { operator: "and", operands: [node.condition, either] };
  }
  // A folded unit-filter after it ("allocated to an ADEPTA SORORITAS unit") names what it happens to.
  if (leaf.parameters.object_filter !== undefined) {
    node.object = structuredClone(leaf.parameters.object_filter as Node);
    // "Destroys an enemy CHARACTER model": the filter names the destroyed model.
    if (node.event === "model-destroyed") (node.object as Node).level = "model";
  }
  if (leaf.parameters.timing !== undefined) {
    const filter = (node.filter ?? {}) as Node;
    node.filter = { ...filter, timing: closed(leaf, "timing") };
  }
  // "When the last Guardian Defender model in this unit is destroyed": the last model of the object's keywords.
  if (leaf.parameters.last === true) node.filter = { ...((node.filter ?? {}) as Node), last: true };
  // "disembarks from a TRANSPORT that is within 6\" of this model" (compile-disembark-moment.ts): which Transports.
  if (leaf.parameters.transport_filter !== undefined) {
    const filter = (node.filter ?? {}) as Node;
    node.filter = { ...filter, transport: structuredClone(leaf.parameters.transport_filter as Node) };
  }
  if (leaf.parameters.object_designated !== undefined) {
    const object = node.object !== null && typeof node.object === "object" && !Array.isArray(node.object) ? node.object as Node : {};
    node.object = { owner: "any", ...object, designated: closed(leaf, "object_designated") };
  }
  const correlated: Node[] = [];
  if (leaf.parameters.same_subject_targeted !== undefined) {
    correlated.push({
      type: "happened",
      parameters: {
        event: "targets-selected",
        subject: "event-subject",
        object: closed(leaf, "same_subject_targeted"),
        filter: { kind: "attack" },
        window: "phase",
      },
    });
  }
  if (leaf.parameters.channelled === true) {
    if (eventBinding === undefined) throw new CompileError("A Channelled Psychic test must bind the exact test event.");
    correlated.push({
      type: "happened",
      parameters: {
        event: "after-roll",
        subject: "event-subject",
        filter: { roll: "channelling", same_rule_as: { event_var: eventBinding } },
        window: "event",
      },
    });
  }
  if (leaf.parameters.before_resolving_activity !== undefined) {
    if (eventBinding === undefined) throw new CompileError("A same-Ritual timing qualifier must bind the exact Psychic test event.");
    correlated.push({
      type: "happened",
      parameters: {
        event: "used",
        subject: "event-subject",
        filter: { kind: closed(leaf, "before_resolving_activity"), same_rule_as: { event_var: eventBinding } },
        window: "event",
      },
    });
  }
  if (leaf.parameters.caused_by_destruction !== undefined) {
    correlated.push(destructionRelationCondition(leaf.parameters.caused_by_destruction, eventBinding, "causes"));
  }
  if (leaf.parameters.causes_destruction !== undefined) {
    correlated.push(destructionRelationCondition(leaf.parameters.causes_destruction, eventBinding, "caused_by"));
  }
  if (correlated.length > 0) {
    const relation = correlated.length === 1 ? correlated[0]! : { operator: "and", operands: correlated };
    node.condition = node.condition === undefined ? relation : { operator: "and", operands: [node.condition, relation] };
  }
  return node;
}

/**
 * "Each time a unit disembarks from this model": any unit's disembarkation from this Transport.
 * The bare moment has no subject, so the DSL default (this unit, the Transport) would name the
 * Transport; a folded unit-filter replaces the `owner: any` subject in `trigger()`.
 */
function disembarkedFromTransport(leaf: CompileLeaf): Node {
  return { event: "disembarked", subject: { owner: "any" }, filter: { transport: closed(leaf, "transport") } };
}

function eventTrigger(leaf: CompileLeaf): Node {
  if (leaf.family_id === "event") {
    const kind = String(leaf.parameters.kind);
    if (kind === "disembarked" && leaf.parameters.transport !== undefined) return disembarkedFromTransport(leaf);
    // move-started takes the same owner, subject and move_types as move-ended.
    if ((OWNED_EVENT_KINDS as readonly string[]).includes(kind) || kind === "move-started") return ownedEventTrigger(leaf);
    if (V7_FILTERED_KINDS[kind]) return V7_FILTERED_KINDS[kind]!(leaf);
    const boundary = phaseTrigger(leaf);
    if (boundary) return boundary;
  }
  const found = TRIGGERS[kindKey(leaf)];
  if (!found) throw new CompileError(`Event ${kindKey(leaf)} has no DSL trigger yet.`);
  const node = structuredClone(found);
  // "each time this unit destroys an enemy unit": who destroyed it, and whose unit it was.
  // A destroyer bound to a folded filter's units ("each time a friendly X unit destroys …") is that filter.
  if (leaf.parameters.by === "filtered-units" && leaf.parameters.subject_filter === undefined) throw new CompileError("event by names the units of a unit-filter, but none sits right before it.");
  if (leaf.parameters.by !== undefined) node.subject = leaf.parameters.by === "enemy" ? { owner: "enemy" } : closed(leaf, "by");
  // A destroyed model's owner names a model, not a unit ("destroys an enemy model").
  // "When this unit destroys a CHARACTER model": the destroyed model's unit keywords (compile-unit-filters.ts folds them in).
  // "The last Guardian Defender model in this unit": keywords with no owner name a model of this unit.
  if (leaf.parameters.object_owner === undefined && leaf.parameters.object_keywords !== undefined) {
    node.object = { member_of: "this-unit", all_of: closed(leaf, "object_keywords"), level: "model" };
  }
  if (leaf.parameters.object_owner !== undefined) node.object = {
    owner: closed(leaf, "object_owner"),
    ...(leaf.parameters.object_keywords !== undefined ? { all_of: closed(leaf, "object_keywords") } : {}),
    // "Destroys a DIRE AVENGERS or GUARDIANS unit": any one of the keywords.
    ...(leaf.parameters.object_any_keywords !== undefined ? { any_of: closed(leaf, "object_any_keywords") } : {}),
    ...(node.event === "model-destroyed" ? { level: "model" } : {}),
  };
  // "An attack made with this model's quake cannon destroys": the attacks that destroy (compile-weapon-qualified.ts).
  // "makes attacks that destroy a unit": attacks of any type narrow nothing.
  if (leaf.parameters.destroy_filter !== undefined && Object.keys(leaf.parameters.destroy_filter as Node).length > 0) {
    if (node.filter !== undefined) throw new CompileError("A destruction already has a filter; it cannot also name its attacks.");
    node.filter = structuredClone(leaf.parameters.destroy_filter as Node);
  }
  if (leaf.parameters.kind === "model-destroyed" && leaf.parameters.attack_type !== undefined && leaf.parameters.attack_type !== "any") {
    const filter = (node.filter ?? {}) as Node;
    const attackType = closed(leaf, "attack_type");
    if (filter.attack_type !== undefined && filter.attack_type !== attackType) throw new CompileError("A destruction names conflicting attack classifications.");
    node.filter = { ...filter, attack_type: attackType };
  }
  // "Each time an attack is allocated to this model".
  if (leaf.parameters.object === "antecedent") throw new CompileError("A moment that names an earlier leaf's unit as its object needs that unit's aura, which names the unit and its range.");
  if (leaf.parameters.object !== undefined) node.object = closed(leaf, "object");
  return node;
}

/**
 * A unit-destroyed moment names the destroyed unit as its object when a later leaf places units
 * "of event-object" (wave 10, set-up placement after a destruction). Other destroyed moments keep
 * their trigger as it was.
 */
export function withDestroyedObject(node: Node, placedFromObject: boolean): Node {
  return node.event === "destroyed" && node.object === undefined && placedFromObject ? { ...node, object: "event-object" } : node;
}
